svg.script:
(function () {
  var DUR = 8000;

var heroEl = document.getElementById('am-hero');
function renderAt(p) {
  if (!heroEl) return;
  var s = Math.sin(2 * Math.PI * p);
  if (Math.abs(s) < 0.06) {
    heroEl.innerHTML = '100M<tspan fill="#2A93A1">+</tspan>';
  } else {
    heroEl.innerHTML = (100 + 8.4 * s).toFixed(1) + 'M<tspan fill="#2A93A1">+</tspan>';
  }
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
